/*
  Muuzee Profile Avatar Picker

  - .profile-avatar-upload opens Popup only.
  - File chooser starts only from Popup upload CTA.
  - Presets reuse the existing profile-settings.js change pipeline.
  - No runtime network request dependency.
*/
(() => {
  "use strict";

  const PRESETS = [
    {name:"avatar-01.webp",src:"./assets/images/avatars/presets/avatar-01.webp",data:"data:image/webp;base64,"},
    {name:"avatar-02.webp",src:"./assets/images/avatars/presets/avatar-02.webp",data:"data:image/webp;base64,"},
    {name:"avatar-03.webp",src:"./assets/images/avatars/presets/avatar-03.webp",data:"data:image/webp;base64,"},
    {name:"avatar-04.webp",src:"./assets/images/avatars/presets/avatar-04.webp",data:"data:image/webp;base64,"},
    {name:"avatar-05.webp",src:"./assets/images/avatars/presets/avatar-05.webp",data:"data:image/webp;base64,"},
    {name:"avatar-06.webp",src:"./assets/images/avatars/presets/avatar-06.webp",data:"data:image/webp;base64,"},
    {name:"avatar-07.webp",src:"./assets/images/avatars/presets/avatar-07.webp",data:"data:image/webp;base64,"},
    {name:"avatar-08.webp",src:"./assets/images/avatars/presets/avatar-08.webp",data:"data:image/webp;base64,"},
    {name:"avatar-09.webp",src:"./assets/images/avatars/presets/avatar-09.webp",data:"data:image/webp;base64,"},
    {name:"avatar-10.webp",src:"./assets/images/avatars/presets/avatar-10.webp",data:"data:image/webp;base64,"},
    {name:"avatar-11.webp",src:"./assets/images/avatars/presets/avatar-11.webp",data:"data:image/webp;base64,"},
    {name:"avatar-12.webp",src:"./assets/images/avatars/presets/avatar-12.webp",data:"data:image/webp;base64,"},
    {name:"avatar-13.webp",src:"./assets/images/avatars/presets/avatar-13.webp",data:"data:image/webp;base64,"},
    {name:"avatar-14.webp",src:"./assets/images/avatars/presets/avatar-14.webp",data:"data:image/webp;base64,"},
    {name:"avatar-15.webp",src:"./assets/images/avatars/presets/avatar-15.webp",data:"data:image/webp;base64,"},
    {name:"avatar-16.webp",src:"./assets/images/avatars/presets/avatar-16.webp",data:"data:image/webp;base64,"},
    {name:"avatar-17.webp",src:"./assets/images/avatars/presets/avatar-17.webp",data:"data:image/webp;base64,"},
    {name:"avatar-18.webp",src:"./assets/images/avatars/presets/avatar-18.webp",data:"data:image/webp;base64,"},
    {name:"avatar-19.webp",src:"./assets/images/avatars/presets/avatar-19.webp",data:"data:image/webp;base64,"},
    {name:"avatar-20.webp",src:"./assets/images/avatars/presets/avatar-20.webp",data:"data:image/webp;base64,"},
    {name:"avatar-21.webp",src:"./assets/images/avatars/presets/avatar-21.webp",data:"data:image/webp;base64,"},
    {name:"avatar-22.webp",src:"./assets/images/avatars/presets/avatar-22.webp",data:"data:image/webp;base64,"},
    {name:"avatar-23.webp",src:"./assets/images/avatars/presets/avatar-23.webp",data:"data:image/webp;base64,"},
    {name:"avatar-24.webp",src:"./assets/images/avatars/presets/avatar-24.webp",data:"data:image/webp;base64,"},
    {name:"avatar-25.webp",src:"./assets/images/avatars/presets/avatar-25.webp",data:"data:image/webp;base64,"},
    {name:"avatar-26.webp",src:"./assets/images/avatars/presets/avatar-26.webp",data:"data:image/webp;base64,"},
    {name:"avatar-27.webp",src:"./assets/images/avatars/presets/avatar-27.webp",data:"data:image/webp;base64,"},
    {name:"avatar-28.webp",src:"./assets/images/avatars/presets/avatar-28.webp",data:"data:image/webp;base64,"},
    {name:"avatar-29.webp",src:"./assets/images/avatars/presets/avatar-29.webp",data:"data:image/webp;base64,"},
    {name:"avatar-30.webp",src:"./assets/images/avatars/presets/avatar-30.webp",data:"data:image/webp;base64,"},
  ];

  const trigger =
    document.querySelector(
      ".profile-avatar-upload"
    );

  const fileInput =
    document.querySelector(
      '[data-avatar-input]'
    )
    || document.querySelector(
      'input[type="file"][accept*="image"]'
    )
    || document.querySelector(
      'input[type="file"]'
    );

  const dialog =
    document.querySelector(
      "[data-profile-avatar-picker]"
    );

  const uploadButton =
    dialog?.querySelector(
      "[data-profile-avatar-picker-upload]"
    );

  const grid =
    dialog?.querySelector(
      "[data-profile-avatar-preset-grid]"
    );

  const scroll =
    dialog?.querySelector(
      "[data-profile-avatar-preset-scroll]"
    );

  const closeButtons =
    dialog?.querySelectorAll(
      "[data-profile-avatar-picker-close]"
    )
    || [];

  if(
    !trigger
    || !fileInput
    || !dialog
    || !uploadButton
    || !grid
    || !scroll
  ){
    return;
  }

  const openPicker =
    () => {
      if(!dialog.open){
        dialog.showModal();
      }
    };

  const closePicker =
    () => {
      if(dialog.open){
        dialog.close();
      }
    };

  /*
    Capture phase + stopImmediatePropagation:
    old direct-file-picker click handlers cannot run.
  */
  trigger.addEventListener(
    "click",
    event => {
      event.preventDefault();
      event.stopImmediatePropagation();
      openPicker();
    },
    true
  );

  uploadButton.addEventListener(
    "click",
    event => {
      event.preventDefault();
      event.stopPropagation();
      fileInput.click();
    }
  );

  fileInput.addEventListener(
    "change",
    () => {
      if(
        fileInput.files
        && fileInput.files.length
      ){
        closePicker();
      }
    }
  );

  closeButtons.forEach(
    button => {
      button.addEventListener(
        "click",
        closePicker
      );
    }
  );

  dialog.addEventListener(
    "click",
    event => {
      if(event.target === dialog){
        closePicker();
      }
    }
  );

  const dataUrlToFile =
    preset => {
      const encoded =
        preset.data.split(",")[1];

      const binary =
        atob(encoded);

      const bytes =
        new Uint8Array(
          binary.length
        );

      for(
        let i = 0;
        i < binary.length;
        i += 1
      ){
        bytes[i] =
          binary.charCodeAt(i);
      }

      return new File(
        [bytes],
        preset.name,
        {
          type:"image/webp"
        }
      );
    };

  const selectPreset =
    (
      preset,
      button
    ) => {
      if(button.disabled){
        return;
      }

      button.disabled = true;

      try {
        const file =
          dataUrlToFile(
            preset
          );

        /*
          profile-settings.js only needs files[0] during the synchronous
          change event. Temporarily shadow the read-only native property,
          dispatch the existing change handler, then restore it.
        */
        Object.defineProperty(
          fileInput,
          "files",
          {
            configurable:true,
            value:[file]
          }
        );

        fileInput.dispatchEvent(
          new Event(
            "change",
            {
              bubbles:true
            }
          )
        );

        delete fileInput.files;

        grid.querySelectorAll(
          "[data-profile-avatar-preset]"
        ).forEach(
          item => {
            item.setAttribute(
              "aria-pressed",
              item === button
                ? "true"
                : "false"
            );
          }
        );

        closePicker();
      } catch(error) {
        try {
          delete fileInput.files;
        } catch(_) {}

        console.error(
          "[Muuzee Avatar Picker]",
          error
        );

        window.alert(
          "アイコンを読み込めませんでした。再度お試しください。"
        );
      } finally {
        button.disabled = false;
      }
    };

  const fragment =
    document.createDocumentFragment();

  PRESETS.forEach(
    (
      preset,
      index
    ) => {
      const button =
        document.createElement(
          "button"
        );

      button.type = "button";
      button.className =
        "profile-avatar-preset";

      button.dataset
        .profileAvatarPreset = "";

      button.setAttribute(
        "aria-label",
        `サンプルアイコン ${index + 1}`
      );

      button.setAttribute(
        "aria-pressed",
        "false"
      );

      const img =
        document.createElement(
          "img"
        );

      img.src = preset.src;
      img.alt = "";
      img.loading =
        index < 10
          ? "eager"
          : "lazy";
      img.decoding = "async";

      button.appendChild(img);

      button.addEventListener(
        "click",
        () =>
          selectPreset(
            preset,
            button
          )
      );

      fragment.appendChild(button);
    }
  );

  grid.appendChild(fragment);

  /* 4 complete rows + 35% of row 5. */
  const syncScrollHeight =
    () => {
      const first =
        grid.querySelector(
          ".profile-avatar-preset"
        );

      if(!first){
        return;
      }

      const rowHeight =
        first.getBoundingClientRect()
          .height;

      const rowGap =
        parseFloat(
          getComputedStyle(grid)
            .rowGap
        )
        || 0;

      if(!rowHeight){
        return;
      }

      scroll.style.maxHeight =
        `${Math.ceil(
          rowHeight * 4.35
          + rowGap * 4
        )}px`;
    };

  requestAnimationFrame(
    syncScrollHeight
  );

  window.addEventListener(
    "resize",
    syncScrollHeight
  );


})();
